'use strict';
const management=globalThis.RasnikiArchangel,el=id=>document.getElementById(id);let records=management.createStore();
function attempt(fn){try{fn();el('status').textContent='Local record updated. Export to keep it after reload.';}catch(error){el('status').textContent=error.message;}}
function renderRecords(){for(const kind of ['accounts','publications']){el(kind).replaceChildren();records[kind].forEach((record,index)=>{const article=document.createElement('article'),summary=document.createElement('p'),remove=document.createElement('button');summary.textContent=Object.entries(record).map(([key,value])=>key+': '+value).join(' · ');remove.type='button';remove.textContent='Delete local record '+(index+1);remove.addEventListener('click',()=>attempt(()=>{management.remove(records,kind,index);renderRecords();}));article.append(summary,remove);el(kind).append(article);});}}
el('save-profile').addEventListener('click',()=>attempt(()=>{records.profile=management.profile({name:el('name').value,bio:el('bio').value,boundary:el('boundary').value});el('profile-status').textContent='Profile updated in this page only.';}));
el('add-account').addEventListener('click',()=>attempt(()=>{management.add(records,'accounts',{service:el('service').value,alias:el('alias').value,note:el('account-note').value});renderRecords();for(const id of ['service','alias','account-note'])el(id).value='';}));
el('add-publication').addEventListener('click',()=>attempt(()=>{management.add(records,'publications',{title:el('title').value,status:el('state').value,reference:el('reference').value,rights:el('rights').value,review:el('review').value});renderRecords();for(const id of ['title','reference','rights','review'])el(id).value='';el('state').value='draft';}));
el('export').addEventListener('click',()=>{try{records.profile=management.profile({name:el('name').value,bio:el('bio').value,boundary:el('boundary').value});const content=management.exportRecords(records),url=URL.createObjectURL(new Blob([content],{type:'application/json'})),link=document.createElement('a');link.href=url;link.download='rasniki-archangel-records.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);el('status').textContent='Unencrypted metadata exported. Support note excluded.';}catch(error){el('status').textContent=error.message;}});
el('clear').addEventListener('click',()=>{records=management.createStore();for(const id of ['name','bio','boundary','service','alias','account-note','title','reference','rights','review','support'])el(id).value='';el('state').value='draft';el('profile-status').textContent='';renderRecords();el('status').textContent='This page’s records and notes cleared; downloaded and remote files are unchanged.';});
function panic(open){el('panic').hidden=!open;el('panic-button').setAttribute('aria-expanded',String(open));(open?el('panic'):el('panic-button')).focus();}
el('panic-button').addEventListener('click',()=>panic(el('panic').hidden));el('close-panic').addEventListener('click',()=>panic(false));el('clear-support').addEventListener('click',()=>{el('support').value='';});
for(const [name,meaning] of management.systems){const article=document.createElement('article'),heading=document.createElement('h3'),definition=document.createElement('p');heading.textContent=name;definition.textContent=meaning;article.append(heading,definition);el('systems').append(article);}renderRecords();
